13: /** Stateful owner of task progress; adapters may only report into this object. */
14: public final class TaskChain {
15:     private static final Gson GSON = new GsonBuilder().disableHtmlEscaping().create();
16: 
17:     // 非 final：懒展开注入二级时需要重建 Goal（把当前未展开一级替换为已展开版本）。
18:     private Goal goal;
19:     private final Map<String, SubtaskStatus> statuses = new LinkedHashMap<>();
20:     private int primaryIndex;
21:     private int subtaskIndex;
22:     private PrimaryGoalStatus primaryStatus = PrimaryGoalStatus.PENDING;
23: 
24:     public TaskChain(Goal goal) {
25:         this.goal = Objects.requireNonNull(goal);
26:         for (PrimaryGoal primary : goal.primaryGoals()) for (Subtask subtask : primary.subtasks()) statuses.put(subtask.id(), SubtaskStatus.PENDING);
27:     }
28:     public Goal goal() { return goal; }
29:     public synchronized PrimaryGoalStatus primaryStatus() { return primaryStatus; }
30: 
31:     /** 当前二级的状态；当前一级"已到达但未展开"（无二级可运行）时为 null。 */
32:     public synchronized SubtaskStatus currentSubtaskStatus() {
33:         Subtask s = currentSubtask();
34:         return s == null ? null : statuses.get(s.id());
35:     }
36: 
37:     /**
38:      * 当前指针指向的二级目标。当前一级为未展开（懒加载、0 个二级）时返回 null——
39:      * 链上没有可运行的当前二级，宿主应先把已生成二级注入再激活；null 不是合法可执行节点。
40:      */
41:     public synchronized Subtask currentSubtask() {
42:         PrimaryGoal cur = currentPrimary();
43:         return cur.unexpanded() ? null : cur.subtasks().get(subtaskIndex);
44:     }
45:     public synchronized PrimaryGoal currentPrimary() { return goal.primaryGoals().get(primaryIndex); }
46: 
47:     /** 当前一级的所有前置资产(waitFor)是否都被 counts 满足（无 waitFor → true）。 */
48:     public synchronized boolean currentPrimaryReady(Map<String, Integer> counts) {
49:         List<AssetRequirement> wf = currentPrimary().waitFor();
50:         if (wf.isEmpty()) return true;
51:         if (counts == null) return false;
52:         for (AssetRequirement r : wf) {
53:             if (counts.getOrDefault(r.assetKey(), 0) < r.minimum()) return false;
54:         }
55:         return true;
56:     }
57: 
58:     /**
59:      * 激活"刚推进到、还没开工"的当前一级（PENDING/WAITING → ACTIVE 并启动其首个二级）。
60:      * 前置资产未到位 → 置 WAITING 并返回 false（监督方此时不该把它派给 AI，等资产到了再调）。
61:      */
62:     public synchronized boolean activateCurrent(Map<String, Integer> counts) {
63:         if (primaryStatus != PrimaryGoalStatus.PENDING && primaryStatus != PrimaryGoalStatus.WAITING) {
64:             throw new IllegalStateException("only a not-yet-started primary may activate: " + primaryStatus);
65:         }
66:         if (currentPrimary().unexpanded()) {
67:             // 未展开 ≠ 依赖未满足：绝不能把"该展开了"误判成 WAITING(缺资产)，也不得进 ACTIVE。
68:             throw new IllegalStateException("current primary unexpanded; expandCurrentPrimary(...) before activation: "
69:                     + currentPrimary().id());
70:         }
71:         if (!currentPrimaryReady(counts)) {
72:             primaryStatus = PrimaryGoalStatus.WAITING;
73:             return false;
74:         }
75:         primaryStatus = PrimaryGoalStatus.ACTIVE;
76:         if (statuses.get(currentSubtask().id()) == SubtaskStatus.PENDING) {
77:             statuses.put(currentSubtask().id(), SubtaskStatus.RUNNING);
78:         }
79:         return true;
80:     }
81: 
82:     public synchronized void startCurrent() {
83:         if (currentPrimary().unexpanded()) {
84:             throw new IllegalStateException("current primary unexpanded; expandCurrentPrimary(...) before start: "
85:                     + currentPrimary().id());
86:         }
87:         if (primaryStatus == PrimaryGoalStatus.PENDING) primaryStatus = PrimaryGoalStatus.ACTIVE;
88:         if (primaryStatus != PrimaryGoalStatus.ACTIVE || statuses.get(currentSubtask().id()) != SubtaskStatus.PENDING) throw new IllegalStateException("current subtask cannot start");
89:         statuses.put(currentSubtask().id(), SubtaskStatus.RUNNING);
90:     }
91: 
92:     /**
93:      * 懒加载唯一合法的注入点：宿主目标驱动器把已为"当前一级"生成的二级集合注入该一级。
94:      * 保持一级的 id/description/waitFor 与 {@link #primaryStatus} 不变，仅 unexpanded→false；
95:      * 注入后照常走依赖门/激活/硬检测。当前一级未展开之外的调用一律拒绝（不重写其他任何状态）。
96:      */
97:     public synchronized void expandCurrentPrimary(List<Subtask> generated) {
98:         PrimaryGoal cur = currentPrimary();
99:         if (!cur.unexpanded()) {
100:             throw new IllegalStateException("current primary already expanded: " + cur.id());
101:         }
102:         if (primaryStatus != PrimaryGoalStatus.PENDING && primaryStatus != PrimaryGoalStatus.WAITING) {
103:             throw new IllegalStateException("only a not-yet-started primary may be expanded: " + primaryStatus);
104:         }
105:         if (generated == null || generated.isEmpty()) {
106:             throw new IllegalArgumentException("expansion requires at least one legal subtask");
107:         }
108:         Set<String> ids = new HashSet<>();
109:         for (Subtask s : generated) {
110:             if (s == null) {
111:                 throw new IllegalArgumentException("null subtask in expansion");
112:             }
113:             if (!ids.add(s.id())) {
114:                 throw new IllegalArgumentException("duplicate subtask id in expansion: " + s.id());
115:             }
116:             if (statuses.containsKey(s.id())) {
117:                 throw new IllegalArgumentException("subtask id already used in chain: " + s.id());
118:             }
119:         }
120:         List<PrimaryGoal> primaries = new ArrayList<>(goal.primaryGoals());
121:         primaries.set(primaryIndex,
122:                 new PrimaryGoal(cur.id(), cur.description(), List.copyOf(generated), cur.waitFor(), false));
123:         goal = new Goal(goal.id(), goal.description(), primaries);
124:         for (Subtask s : generated) {
125:             statuses.put(s.id(), SubtaskStatus.PENDING);
126:         }
127:         subtaskIndex = 0;
128:     }
