130:     public synchronized boolean applyHardCodedResult(String subtaskId, boolean satisfied) {
131:         requireCurrent(subtaskId);
132:         if (currentSubtask().detectionMode() != DetectionMode.HARD_CODED) throw new IllegalStateException("current subtask is not hard-coded");
133:         if (statuses.get(subtaskId) != SubtaskStatus.RUNNING) throw new IllegalStateException("current subtask is not running");
134:         if (!satisfied) return false;
135:         statuses.put(subtaskId, SubtaskStatus.COMPLETED);
136:         advanceOrAwait();
137:         return true;
138:     }
