140:     public synchronized boolean applyAiAssistedResult(String subtaskId, String result) {
141:         requireCurrent(subtaskId);
142:         if (currentSubtask().detectionMode() != DetectionMode.AI_ASSISTED) throw new IllegalStateException("current subtask is not AI-assisted");
143:         if (statuses.get(subtaskId) != SubtaskStatus.RUNNING) throw new IllegalStateException("current subtask is not running");
144:         Objects.requireNonNull(result);
145:         if (!"CONFIRMED".equals(result)) return false;
146:         statuses.put(subtaskId, SubtaskStatus.COMPLETED);
147:         advanceOrAwait();
148:         return true;
149:     }
