151:     public synchronized void applySupervisorDecision(SupervisorDecision decision) {
152:         Objects.requireNonNull(decision);
153:         if (primaryStatus != PrimaryGoalStatus.AWAITING_SUPERVISOR || !currentPrimary().id().equals(decision.targetNodeId())) throw new IllegalStateException("supervisor decision does not match current primary goal");
154:         switch (decision.type()) {
155:             case CONFIRM -> {
156:                 primaryStatus = PrimaryGoalStatus.COMPLETED;
157:                 if (primaryIndex + 1 < goal.primaryGoals().size()) {
158:                     primaryIndex++;
159:                     subtaskIndex = 0;
160:                     primaryStatus = PrimaryGoalStatus.PENDING;
161:                 }
162:             }
163:             case REJECT, REPLAN -> primaryStatus = PrimaryGoalStatus.REPLANNING;
164:             case NEED_MORE_EVIDENCE, DEFER -> primaryStatus = PrimaryGoalStatus.WAITING;
165:         }
166:     }
