168:     public synchronized void markFailed(String subtaskId, String reason) {
169:         requireCurrent(subtaskId);
170:         SubtaskStatus st = statuses.get(subtaskId);
171:         if (st != SubtaskStatus.RUNNING && st != SubtaskStatus.STALLED) throw new IllegalStateException("current subtask is not running/stalled");
172:         if (reason == null || reason.isBlank()) throw new IllegalArgumentException("failure reason required");
173:         statuses.put(subtaskId, SubtaskStatus.FAILED);
174:     }
