176:     /** 监督检测到卡死（资产/工具长时间无变化）→ 置 STALLED，等待外部拍醒或升级。 */
177:     public synchronized void markStalled(String subtaskId, String reason) {
178:         requireCurrent(subtaskId);
179:         if (statuses.get(subtaskId) != SubtaskStatus.RUNNING) throw new IllegalStateException("current subtask is not running");
180:         if (reason == null || reason.isBlank()) throw new IllegalArgumentException("stall reason required");
181:         statuses.put(subtaskId, SubtaskStatus.STALLED);
182:     }
