184:     /** 监督拍醒后，检测到行为恢复 → 从 STALLED 回到 RUNNING（任务继续）。 */
185:     public synchronized void resumeFromStalled(String subtaskId) {
186:         requireCurrent(subtaskId);
187:         if (statuses.get(subtaskId) != SubtaskStatus.STALLED) throw new IllegalStateException("current subtask is not stalled");
188:         statuses.put(subtaskId, SubtaskStatus.RUNNING);
189:     }
