191:     /** Level 2 局部恢复：失败的当前二级重置为 PENDING，可重新 startCurrent（AI 换策略再试）。 */
192:     public synchronized void retrySubtask(String subtaskId) {
193:         requireCurrent(subtaskId);
194:         if (statuses.get(subtaskId) != SubtaskStatus.FAILED) throw new IllegalStateException("only a FAILED subtask may retry");
195:         statuses.put(subtaskId, SubtaskStatus.PENDING);
196:     }
