202:     /** Read-only structured view for monitoring; it is derived from the state owner. */
203:     public synchronized Map<String, Object> snapshot() {
204:         List<Map<String, Object>> primaries = new ArrayList<>();
205:         for (int p = 0; p < goal.primaryGoals().size(); p++) {
206:             PrimaryGoal primary = goal.primaryGoals().get(p);
207:             List<Map<String, Object>> subtasks = new ArrayList<>();
208:             for (int s = 0; s < primary.subtasks().size(); s++) {
209:                 Subtask subtask = primary.subtasks().get(s);
