214:                 item.put("detectionMode", subtask.detectionMode().name());
215:                 item.put("condition", subtask.condition());
216:                 item.put("current", p == primaryIndex && s == subtaskIndex);
217:                 subtasks.add(item);
218:             }
219:             Map<String, Object> primaryView = new LinkedHashMap<>();
220:             primaryView.put("id", primary.id());
221:             primaryView.put("description", primary.description());
222:             primaryView.put("current", p == primaryIndex);
223:             primaryView.put("unexpanded", primary.unexpanded());
224:             if (!primary.waitFor().isEmpty()) {
225:                 List<Map<String, Object>> wf = new ArrayList<>();
226:                 for (AssetRequirement r : primary.waitFor()) {
227:                     Map<String, Object> m = new LinkedHashMap<>();
228:                     m.put("asset_key", r.assetKey());
229:                     m.put("minimum", r.minimum());
230:                     wf.add(m);
231:                 }
232:                 primaryView.put("waitFor", wf);
233:             }
234:             primaryView.put("subtasks", subtasks);
235:             primaries.add(primaryView);
236:         }
237:         Map<String, Object> view = new LinkedHashMap<>();
238:         view.put("goalId", goal.id());
239:         view.put("description", goal.description());
240:         view.put("primaryStatus", primaryStatus.name());
241:         view.put("primaryIndex", primaryIndex);
242:         view.put("subtaskIndex", subtaskIndex);
243:         PrimaryGoal current = currentPrimary();
244:         view.put("currentPrimaryId", current.id());
245:         // 当前一级未展开时诚实报"无当前二级"，而不是伪造占位节点。
246:         view.put("currentSubtaskId", current.unexpanded() ? null : currentSubtask().id());
247:         if (primaryStatus == PrimaryGoalStatus.WAITING && !current.waitFor().isEmpty()) {
248:             view.put("waitingFor", currentPrimary().waitFor().stream().map(AssetRequirement::assetKey).toList());
249:         }
250:         view.put("primaries", primaries);
251:         return view;
252:     }
