254:     /** 导出任务链状态为 JSON（持久化用：goal 结构 + 全部状态 + 当前指针）。 */
255:     public synchronized String toJson() {
256:         JsonObject o = new JsonObject();
257:         o.add("goal", GSON.toJsonTree(goal));
258:         JsonObject st = new JsonObject();
259:         for (Map.Entry<String, SubtaskStatus> e : statuses.entrySet()) {
260:             st.addProperty(e.getKey(), e.getValue().name());
261:         }
262:         o.add("statuses", st);
263:         o.addProperty("primaryIndex", primaryIndex);
264:         o.addProperty("subtaskIndex", subtaskIndex);
265:         o.addProperty("primaryStatus", primaryStatus.name());
266:         return GSON.toJson(o);
267:     }
