269:     /** 从 JSON 恢复任务链状态（游戏重启后 RECOVERING）。 */
270:     public static TaskChain fromJson(String json) {
271:         JsonObject o = JsonParser.parseString(json).getAsJsonObject();
272:         JsonObject goalObj = o.getAsJsonObject("goal");
273:         // 旧链兼容（A-1 前无 unexpanded 字段）：解析树里给缺该字段的一级补 false=已展开，
274:         // 不依赖 Gson 对缺失原始类型组件的默认行为。waitFor 等引用组件缺失 → 构造器已置空。
275:         JsonArray primaries = goalObj.getAsJsonArray("primaryGoals");
276:         for (JsonElement el : primaries) {
277:             JsonObject pg = el.getAsJsonObject();
278:             if (!pg.has("unexpanded")) {
279:                 pg.addProperty("unexpanded", false);
280:             }
281:         }
282:         Goal goal = GSON.fromJson(goalObj, Goal.class);
283:         TaskChain chain = new TaskChain(goal);
284:         JsonObject st = o.getAsJsonObject("statuses");
285:         for (String k : st.keySet()) {
286:             chain.statuses.put(k, SubtaskStatus.valueOf(st.get(k).getAsString()));
287:         }
